    #[derive(Clone, Debug, PartialEq)]
    pub enum Request {
        /// destroy the xdg_toplevel
        Destroy,
        /// set the parent of this surface
        SetParent {
            /// parent surface for this surface
            parent: Option<ObjectId>,
        },
        /// set surface title
        SetTitle {
            /// title of the surface
            title: String,
        },
        /// set application ID
        SetAppId {
            /// application identifier surface belongs to
            app_id: String,
        },
        /// show the window menu
        ShowWindowMenu {
            /// the wl_seat of the user event
            seat: ObjectId,
            /// the serial of the user event
            serial: u32,
            /// the x position to pop up the window menu at
            x: i32,
            /// the y position to pop up the window menu at
            y: i32,
        },
        /// start an interactive move
        Move {
            /// the wl_seat of the user event
            seat: ObjectId,
            /// the serial of the user event
            serial: u32,
        },
        /// start an interactive resize
        Resize {
            /// the wl_seat of the user event
            seat: ObjectId,
            /// the serial of the user event
            serial: u32,
            /// which edge or corner is being dragged
            edges: u32,
        },
        /// set the maximum size
        SetMaxSize {
            /// maximum width of the window
            width: i32,
            /// maximum height of the window
            height: i32,
        },
        /// set the minimum size
        SetMinSize {
            /// minimum width of the window
            width: i32,
            /// minimum height of the window
            height: i32,
        },
        /// maximize the window
        SetMaximized,
        /// unmaximize the window
        UnsetMaximized,
        /// set the window as fullscreen on an output
        SetFullscreen {
            /// preferred output to place surface on
            output: Option<ObjectId>,
        },
        /// unset the window as fullscreen
        UnsetFullscreen,
        /// set the window as minimized
        SetMinimized,
    }

    impl Request {
        /// The message's opcode.
        pub fn opcode(&self) -> u16 {
            match self {
                Request::Destroy => 0,
                Request::SetParent { .. } => 1,
                Request::SetTitle { .. } => 2,
                Request::SetAppId { .. } => 3,
                Request::ShowWindowMenu { .. } => 4,
                Request::Move { .. } => 5,
                Request::Resize { .. } => 6,
                Request::SetMaxSize { .. } => 7,
                Request::SetMinSize { .. } => 8,
                Request::SetMaximized => 9,
                Request::UnsetMaximized => 10,
                Request::SetFullscreen { .. } => 11,
                Request::UnsetFullscreen => 12,
                Request::SetMinimized => 13,
            }
        }

        /// The message `opcode` with `args` (from [`crate::wire::decode_args`]).
        pub fn from_args(opcode: u16, args: Vec<Arg>) -> Result<Request, WireError> {
            let mut a = Args::new(args);
            let m = match opcode {
                0 => Request::Destroy,
                1 => Request::SetParent { parent: a.object_opt()? },
                2 => Request::SetTitle { title: a.string()? },
                3 => Request::SetAppId { app_id: a.string()? },
                4 => Request::ShowWindowMenu { seat: a.object()?, serial: a.uint()?, x: a.int()?, y: a.int()? },
                5 => Request::Move { seat: a.object()?, serial: a.uint()? },
                6 => Request::Resize { seat: a.object()?, serial: a.uint()?, edges: a.uint()? },
                7 => Request::SetMaxSize { width: a.int()?, height: a.int()? },
                8 => Request::SetMinSize { width: a.int()?, height: a.int()? },
                9 => Request::SetMaximized,
                10 => Request::UnsetMaximized,
                11 => Request::SetFullscreen { output: a.object_opt()? },
                12 => Request::UnsetFullscreen,
                13 => Request::SetMinimized,
                _ => return Err(WireError::BadOpcode(opcode)),
            };
            a.end()?;
            Ok(m)
        }

        /// The message's arguments, for [`crate::wire::encode`].
        pub fn into_args(self) -> Vec<Arg> {
            match self {
                Request::Destroy => Vec::new(),
                Request::SetParent { parent } => alloc::vec![Arg::Object(parent)],
                Request::SetTitle { title } => alloc::vec![Arg::Str(Some(title))],
                Request::SetAppId { app_id } => alloc::vec![Arg::Str(Some(app_id))],
                Request::ShowWindowMenu { seat, serial, x, y } => {
                    alloc::vec![Arg::Object(Some(seat)), Arg::Uint(serial), Arg::Int(x), Arg::Int(y)]
                }
                Request::Move { seat, serial } => alloc::vec![Arg::Object(Some(seat)), Arg::Uint(serial)],
                Request::Resize { seat, serial, edges } => {
                    alloc::vec![Arg::Object(Some(seat)), Arg::Uint(serial), Arg::Uint(edges)]
                }
                Request::SetMaxSize { width, height } => alloc::vec![Arg::Int(width), Arg::Int(height)],
                Request::SetMinSize { width, height } => alloc::vec![Arg::Int(width), Arg::Int(height)],
                Request::SetMaximized => Vec::new(),
                Request::UnsetMaximized => Vec::new(),
                Request::SetFullscreen { output } => alloc::vec![Arg::Object(output)],
                Request::UnsetFullscreen => Vec::new(),
                Request::SetMinimized => Vec::new(),
            }
        }
    }

